'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const steps=[
 ['Grundlagen','Dein Projekt beginnt hier.','Gib deiner Idee einen Rahmen. Du kannst alle Angaben später anpassen.',[['title','Arbeitstitel','text','Ein präziser Titel kann später entstehen.'],['name','Name','text'],['className','Klasse / Schule','text'],['supervisor','Betreuungsperson','text'],['subject','Fach / Themengebiet','text'],['motivation','Ausgangslage und Motivation','textarea','Was interessiert dich daran? Für wen ist die Untersuchung relevant?'],['goal','Ziel und eigener Beitrag','textarea','Was willst du herausfinden, erklären oder gestalten?']], 'Vom Interesse zum Thema','Sammle Ideen und grenze dein Thema ein. Ein persönliches Interesse trägt dich durch die Arbeit; ein klares Ziel gibt ihr Richtung.'],
 ['Forschungsfrage','Eine Frage, die dich weiterbringt.','Formuliere eine offene, eingegrenzte und mit deinen Mitteln beantwortbare Frage.',[['question','Hauptfragestellung','textarea','Zum Beispiel: Wie unterscheiden sich die Darstellungen von … in … und … anhand von …?'],['scope','Themeneingrenzung und Begriffe','textarea','Welche Fälle, Personen, Werke, Orte und Zeiträume untersuchst du? Was bleibt ausgeklammert?'],['subquestions','Teilfragen','textarea','Welche zwei bis vier Teilfragen führen zur Antwort? Eine pro Zeile.'],['hypothesis','Erwartung / Arbeitshypothese (optional)','textarea','Eine begründete Vermutung, die auch widerlegt werden darf.'],['feasibility','Praktikabilität und Zugang','textarea','Wie erhältst du Material oder Daten? Reichen Zeit, Fähigkeiten und Ressourcen?']], 'Klein genug, um tief zu gehen','Eine gute Forschungsfrage nennt einen konkreten Gegenstand und ein Erkenntnisziel. «Alles über …» ist ein Thema, aber noch keine Forschungsfrage.'],
 ['Methode','So wird aus einer Frage eine Antwort.','Beschreibe, wie du vorgehst und woran du deine Ergebnisse beurteilst.',[['method','Hauptmethode','select'],['material','Material / Stichprobe','textarea','Welche Texte, Daten, Fälle oder Personen? Wie viele und nach welchen Auswahlkriterien?'],['procedure','Durchführung und Instrumente','textarea','Welche Arbeitsschritte, Interviewfragen, Messgeräte oder Analysekategorien nutzt du?'],['analysis','Auswertung','textarea','Wie wertest du das Material aus? Welche Kriterien oder Kategorien verwendest du?'],['limits','Grenzen, Ethik und Datenschutz','textarea','Was kann deine Methode nicht zeigen? Einwilligung, Anonymisierung, Rechte und sichere Datenablage klären.']], 'Methode folgt der Frage','Literaturanalyse, Vergleich, Interview, Umfrage oder Experiment: Entscheidend ist, ob die Methode deine Frage beantworten kann. Plane auch einen kleinen Probelauf.'],
 ['Literatur & Recherche','Finde Material, das dich weiterbringt.','Dokumentiere echte Quellen und ihre Eignung. Das Tool erfindet keine Literatur.',[['keywords','Suchbegriffe und Suchkombinationen','textarea','Begriffe, Synonyme, englische Übersetzungen; Kombinationen mit AND / OR.'],['places','Suchorte und Zugänge','textarea','Bibliothekskataloge, Fachdatenbanken, Archive, Fachzeitschriften, Expertinnen und Experten.'],['literature','Vorläufiges Literaturverzeichnis','textarea','Je Quelle: Autor/in, Jahr, Titel, Verlag / Zeitschrift, DOI / URL, bei Websites Abrufdatum.'],['sourcecheck','Quellenbewertung und Verwendung','textarea','Autorität, Aktualität, Belege und Perspektive prüfen. Welche Quelle hilft bei welcher Teilfrage?'],['researchlog','Rechercheprotokoll','textarea','Datum | Suchort | Suchanfrage | Ergebnis | nächster Schritt. Auch erfolglose Suchen festhalten.']], 'Recherchieren heisst auswählen','Beginne mit einem Überblick, suche dann gezielt. Kombiniere Bibliothek und digitale Recherche. Halte Zitate von Anfang an mit Seitenangaben fest.'],
 ['Vorgehen','Die nächsten Schritte werden konkret.','Plane Aufbau, Betreuung und mögliche Stolpersteine.',[['outline','Vorläufige Gliederung','textarea','Einleitung · Grundlagen · Methode · Ergebnisse · Diskussion · Fazit · Quellen · Anhang'],['workflow','Arbeitsorganisation und Dokumentation','textarea','Arbeitsjournal, Dateinamen, Versionen, Backups und Umgang mit Hilfsmitteln festlegen.'],['meetings','Betreuung und Rückmeldungen','textarea','Wann besprichst du Konzept, Methode, erste Ergebnisse und Rohfassung?'],['risks','Risiken und Alternativen','textarea','Was machst du bei fehlendem Datenzugang, Absagen oder wenig Rücklauf?'],['resources','Ressourcen und offene Fragen','textarea','Kosten, Geräte, Bewilligungen, Hilfe und schulische Vorgaben.']], 'Den Prozess mitdenken','Plane Rückmeldungen ein, bevor wichtige Entscheidungen feststehen. Ein Arbeitsjournal macht Entscheidungen und Veränderungen nachvollziehbar.'],
 ['Zeitplan','Ein Plan, der mit dir mitwächst.','Start und Abgabe setzen den Rahmen. Passe Phasen an und markiere Erledigtes.',[], 'Reserve ist Arbeitszeit','Rechne mit Verzögerungen. Sichere Zeit für Überarbeitung, Quellenkontrolle und Abgabe. Bei neuen Terminen kannst du alle Phasen neu verteilen.']];
const phaseNames=['Thema & Konzept klären','Literatur recherchieren','Methode vorbereiten & testen','Material erheben / analysieren','Auswerten & Rohfassung schreiben','Feedback & Überarbeitung','Schlusskontrolle & Abgabe'];
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
let state={version:1,type:'Maturarbeit',step:0,data:{start:today(),deadline:''},tasks:[]};let storageOK=true;try{const s=JSON.parse(localStorage.getItem('konzeptstudio-v1'));if(s&&s.version===1&&s.data&&Array.isArray(s.tasks))state=s}catch{};
function save(){try{localStorage.setItem('konzeptstudio-v1',JSON.stringify(state));$('#saved').textContent='Automatisch gespeichert'}catch{storageOK=false;$('#saved').textContent='Bitte Sicherung exportieren'}updateProgress()}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3000)}
function updateProgress(){const keys=steps.flatMap(s=>s[3].map(f=>f[0])).filter(k=>k!=='hypothesis');keys.push('start','deadline');const done=keys.filter(k=>String(state.data[k]||'').trim()).length;const p=Math.round(done/keys.length*100);$('#percent').textContent=p+'%';$('#progress').style.width=p+'%';$('#progressText').textContent=`${done} von ${keys.length} Angaben erfasst · keine Qualitätsbewertung`}
function field(f){const[k,label,type,hint]=f,v=state.data[k]||'';return `<label for="${k}">${label}</label>${type==='textarea'?`<textarea id="${k}" data-key="${k}">${esc(v)}</textarea>`:type==='select'?`<select id="${k}" data-key="${k}">${['','Literatur- / Textanalyse','Vergleichende Analyse','Qualitative Interviews','Quantitative Umfrage','Experiment / Messung','Beobachtung','Gestalterisch-praktische Arbeit','Methodenkombination'].map(x=>`<option ${v===x?'selected':''}>${x}</option>`).join('')}</select>`:`<input id="${k}" data-key="${k}" type="${type}" value="${esc(v)}">`}${hint?`<p class="hint">${hint}</p>`:''}`}
function render(){const s=steps[state.step];$('#nav').innerHTML=steps.map((x,i)=>`<button class="${i===state.step?'active':''}" data-step="${i}"><small>${String(i+1).padStart(2,'0')}</small>${x[0]}</button>`).join('');document.querySelectorAll('[data-type]').forEach(b=>{b.classList.toggle('selected',b.dataset.type===state.type);b.setAttribute('aria-pressed',String(b.dataset.type===state.type))});$('#stepLabel').textContent=`SCHRITT 0${state.step+1} / 06`;$('#stepTitle').textContent=s[1];$('#stepIntro').textContent=s[2];$('#tipTitle').textContent=s[4];$('#tip').textContent=s[5];$('#fields').innerHTML=state.step===5?timeline():s[3].map(field).join('');if(state.step===1){$('#fields').insertAdjacentHTML('beforeend','<div class="feedback" id="qcheck"></div>');checkQuestion()}$('#back').disabled=state.step===0;$('#next').textContent=state.step===5?'Konzept ansehen ↗':'Weiter →';updateProgress();}
function checkQuestion(){const q=String(state.data.question||'').trim();const checks=[[q.length>=35,'Formuliere eine vollständige Frage mit konkretem Erkenntnisziel.'],[/^(wie|welche|welcher|welches|inwiefern|inwieweit|warum|unter welchen|wodurch|was)\b/i.test(q),'Nutze eine offene Frage statt einer reinen Ja-/Nein-Frage.'],[(state.data.scope||'').trim().length>=25,'Grenze Untersuchungsgegenstand, Zeitraum oder Personengruppe ein.'],[(state.data.feasibility||'').trim().length>=25,'Begründe den Zugang zu Daten und die Machbarkeit.']];$('#qcheck').innerHTML='<strong>Fragencheck · Orientierung</strong><ul>'+checks.map(([ok,t])=>`<li>${ok?'✓':'○'} ${esc(t)}</li>`).join('')+'</ul><span class="hint">Formale Hinweise, keine automatische fachliche Freigabe. Besprich Frage und Methode mit deiner Betreuung.</span>'}
const dateNum=d=>/^\d{4}-\d{2}-\d{2}$/.test(d||'')?Date.parse(d+'T00:00:00Z'):NaN;const iso=n=>new Date(n).toISOString().slice(0,10);const fmt=d=>Number.isFinite(dateNum(d))?new Date(d+'T12:00:00').toLocaleDateString('de-CH'):'offen';
function generatePlan(){let a=dateNum(state.data.start),b=dateNum(state.data.deadline);if(!Number.isFinite(a)||!Number.isFinite(b)||b-a<6*86400000){toast('Bitte Start und Abgabe mit mindestens 7 Kalendertagen wählen.');return}const days=Math.round((b-a)/86400000)+1, weights=[.10,.15,.10,.25,.20,.14,.06],extra=days-7,durations=weights.map(w=>1+Math.floor(extra*w));let rest=days-durations.reduce((x,y)=>x+y,0);for(let i=0;rest>0;i=(i+1)%7,rest--)durations[i]++;let cursor=a;state.tasks=phaseNames.map((name,i)=>{const start=iso(cursor);cursor+=durations[i]*86400000;return {name,start,end:iso(cursor-86400000),done:false}});save();render();warnings();}
function planWarnings(){const a=dateNum(state.data.start),b=dateNum(state.data.deadline),warnings=[];if(!Number.isFinite(a)||!Number.isFinite(b))warnings.push('Start und Abgabe fehlen oder sind ungültig.');else if(b<=a)warnings.push('Die Abgabe muss nach dem Start liegen.');state.tasks.forEach((t,i)=>{const x=dateNum(t.start),y=dateNum(t.end);if(!Number.isFinite(x)||!Number.isFinite(y)||y<x)warnings.push(`${t.name}: Datumsbereich prüfen.`);else{if(x<a||y>b)warnings.push(`${t.name}: liegt ausserhalb des Projektrahmens.`);if(!t.done&&y<dateNum(today()))warnings.push(`${t.name}: überfällig.`);if(i&&x<=dateNum(state.tasks[i-1].end))warnings.push(`${t.name}: überschneidet sich mit der vorigen Phase.`)}});return warnings}
function timeline(){return `<div class="row">${field(['start','Projektstart','date'])}${field(['deadline','Abgabetermin','date'])}</div>${field(['hours','Verfügbare Stunden pro Woche','number'])}${field(['commitments','Ferien, Prüfungen und weitere Verpflichtungen','textarea','Trage Engpässe ein und passe die Phasentermine entsprechend an.'])}<div class="actions"><button id="generate" class="primary">${state.tasks.length?'Phasen neu verteilen':'Zeitplan erstellen'}</button><button id="importBtn">Sicherung importieren</button></div><p class="hint">Neu verteilen ersetzt die Phasentermine und setzt Erledigt-Markierungen zurück. Mindestens 7 Kalendertage erforderlich.</p><div id="planWarnings" class="feedback"></div><div class="timeline">${state.tasks.map((t,i)=>`<div class="task"><div class="task-head"><input type="checkbox" aria-label="${esc(t.name)} erledigt" data-task="${i}" data-prop="done" ${t.done?'checked':''}><strong>${esc(t.name)}</strong></div><div class="row"><div><label for="ts${i}">Von</label><input id="ts${i}" type="date" data-task="${i}" data-prop="start" value="${esc(t.start)}"></div><div><label for="te${i}">Bis</label><input id="te${i}" type="date" data-task="${i}" data-prop="end" value="${esc(t.end)}"></div></div><div class="bar"><div style="width:${t.done?100:0}%"></div></div></div>`).join('')}</div>`}
function warnings(){if($('#planWarnings')){const w=planWarnings();$('#planWarnings').innerHTML=w.length?'<strong>Plan prüfen</strong><ul>'+w.map(t=>`<li>${esc(t)}</li>`).join('')+'</ul>':'✓ Alle Phasen liegen im Projektrahmen. Änderungen werden sofort gespeichert.'}}
function conceptSections(){return [
 {title:'Arbeitstitel',fields:[['title','',false]]},
 {title:'Allgemeine Angaben',fields:[['name','Name'],['className','Klasse / Schule'],['supervisor','Betreuungsperson'],['subject','Fach / Themengebiet']]},
 {title:'Ausgangslage und Motivation',fields:[['motivation','',false]]},
 {title:'Fragestellung und Ziel',fields:[['question','Hauptfragestellung'],['subquestions','Unterfragen',true],['goal','Ziel der Arbeit'],['hypothesis','Erwartung / Arbeitshypothese']]},
 {title:'Themeneingrenzung',fields:[['scope','',true],['feasibility','Praktikabilität und Zugang']]},
 {title:'Vorgehensweise und Methoden',fields:[['method','Hauptmethode'],['material','Material / Stichprobe'],['procedure','Durchführung und Instrumente'],['analysis','Auswertung'],['limits','Grenzen, Ethik und Datenschutz'],['risks','Herausforderungen und Alternativen']]},
 {title:'Vorläufige Gliederung',fields:[['outline','',true]]},
 {title:'Literatur und Recherche',fields:[['literature','Vorläufiges Literaturverzeichnis',true],['keywords','Suchbegriffe und Suchkombinationen'],['places','Suchorte und Zugänge'],['sourcecheck','Quellenbewertung und Verwendung'],['researchlog','Rechercheprotokoll']]},
 {title:'Arbeitsorganisation und Betreuung',fields:[['workflow','Arbeitsorganisation und Dokumentation'],['meetings','Betreuung und Rückmeldungen'],['resources','Ressourcen und offene Fragen']]}
]}
function conceptTitle(){return state.type==='Maturarbeit'?'Konzept Maturaarbeit':'Konzept Selbständige Arbeit'}
function content(){let out=`# ${conceptTitle()}\n`;for(const section of conceptSections()){out+=`\n## ${section.title}\n`;for(const[k,label,list]of section.fields){const value=String(state.data[k]||'').trim();if(k==='hypothesis'&&!value)continue;if(label)out+=`\n**${label}:**\n`;out+=`\n${value?(list?value.split(/\n+/).map(x=>'- '+x.replace(/^\s*[-•]\s*/, '')).join('\n'):value):'Noch zu ergänzen'}\n`}}out+=`\n## Vorläufiger Zeitplan\n\nProjektstart: ${fmt(state.data.start)}\nAbgabe: ${fmt(state.data.deadline)}\nStunden pro Woche: ${state.data.hours||'Noch zu ergänzen'}\nWeitere Verpflichtungen: ${state.data.commitments||'Noch zu ergänzen'}\n\n`;state.tasks.forEach(t=>out+=`- [${t.done?'x':' '}] ${t.name}: ${fmt(t.start)} – ${fmt(t.end)}\n`);if(!state.tasks.length)out+='Zeitplan noch erstellen.\n';const w=planWarnings();if(w.length)out+='\nHinweise zum Zeitplan:\n'+w.map(x=>'- '+x).join('\n');return out}
function conceptHTML(){let html=`<h1>${esc(conceptTitle())}</h1>`;for(const section of conceptSections()){html+=`<h2>${esc(section.title)}</h2>`;for(const[k,label,list]of section.fields){const value=String(state.data[k]||'').trim();if(k==='hypothesis'&&!value)continue;if(label)html+=`<h3>${esc(label)}:</h3>`;html+=value?(list?'<ul>'+value.split(/\n+/).map(x=>`<li>${esc(x.replace(/^\s*[-•]\s*/, ''))}</li>`).join('')+'</ul>':`<p>${esc(value)}</p>`):'<p class="missing">Noch zu ergänzen</p>'}}
html+=`<h2>Vorläufiger Zeitplan</h2><p>${fmt(state.data.start)} – ${fmt(state.data.deadline)} · ${esc(state.data.hours||'offen')} Stunden / Woche</p><p>Weitere Verpflichtungen: ${esc(state.data.commitments||'Noch zu ergänzen')}</p>`;if(state.tasks.length)html+=`<table><thead><tr><th>Arbeitsschritt</th><th>Von</th><th>Bis</th><th>Status</th></tr></thead><tbody>${state.tasks.map(t=>`<tr><td>${esc(t.name)}</td><td>${fmt(t.start)}</td><td>${fmt(t.end)}</td><td>${t.done?'Erledigt':'Offen'}</td></tr>`).join('')}</tbody></table>`;else html+='<p class="missing">Zeitplan noch erstellen.</p>';const w=planWarnings();if(w.length)html+='<p class="danger">'+w.map(esc).join('<br>')+'</p>';return html}
function preview(){$('#document').innerHTML=conceptHTML();$('#preview').showModal()}
function download(text,name,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.step){state.step=Number(b.dataset.step);save();render();warnings()}if(b.dataset.type){state.type=b.dataset.type;save();render();warnings()}if(b.id==='generate')generatePlan();if(b.id==='importBtn')$('#import').click()});
$('#fields').addEventListener('input',e=>{const k=e.target.dataset.key;if(k){state.data[k]=e.target.value;save();if(state.step===1)checkQuestion();warnings()}const t=e.target.dataset.task;if(t!==undefined){state.tasks[Number(t)][e.target.dataset.prop]=e.target.type==='checkbox'?e.target.checked:e.target.value;save();warnings();if(e.target.type==='checkbox')e.target.closest('.task').querySelector('.bar>div').style.width=e.target.checked?'100%':'0%'}});
$('#back').onclick=()=>{if(state.step>0){state.step--;save();render();warnings()}};$('#next').onclick=()=>{if(state.step===5)preview();else{state.step++;save();render();warnings()}};$('#previewBtn').onclick=preview;$('#close').onclick=()=>$('#preview').close();$('#print').onclick=()=>window.print();$('#markdown').onclick=()=>download(content(true),'konzept.md','text/markdown;charset=utf-8');$('#json').onclick=()=>download(JSON.stringify(state,null,2),'konzept-sicherung.json','application/json');
$('#import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const s=JSON.parse(await file.text());if(s.version!==1||!s.data||typeof s.data!=='object'||Array.isArray(s.data)||!Array.isArray(s.tasks)||s.tasks.length>30||!['Maturarbeit','Selbständige Arbeit'].includes(s.type))throw Error();for(const v of Object.values(s.data))if(typeof v!=='string'||v.length>100000)throw Error();for(const t of s.tasks)if(typeof t.name!=='string'||typeof t.start!=='string'||typeof t.end!=='string'||typeof t.done!=='boolean')throw Error();if(!confirm('Aktuelles Konzept durch diese Sicherung ersetzen?'))return;state={version:1,type:s.type,step:0,data:s.data,tasks:s.tasks};save();render();toast('Sicherung importiert.')}catch{toast('Diese Datei ist keine gültige Konzeptstudio-Sicherung.')}e.target.value=''};
$('#demo').onclick=()=>{if(Object.values(state.data).some((v,i)=>v&& !['start','deadline'].includes(Object.keys(state.data)[i]))&&!confirm('Aktuelle Eingaben durch das Beispiel ersetzen? Sichere dein Konzept vorher über «Konzept ansehen».'))return;state.data={start:today(),deadline:iso(dateNum(today())+120*86400000),title:'Erzählperspektiven und Verantwortung in «Der Besuch der alten Dame»',name:'Beispiel – eigene Angaben einsetzen',subject:'Deutsch / Literatur',motivation:'Mich interessiert, wie eine Gemeinschaft moralische Entscheidungen sprachlich rechtfertigt.',goal:'Ich untersuche am Dramentext, wie sich die Rechtfertigungen der Güllener im Verlauf der Handlung verändern.',question:'Wie verändern sich die sprachlichen Rechtfertigungen der Güllener für ihr Handeln gegenüber Ill in den drei Akten von «Der Besuch der alten Dame»?',scope:'Untersucht werden Äusserungen des Bürgermeisters und des Lehrers in den drei Akten. Biografische Deutungen und Inszenierungen bleiben ausgeklammert.',subquestions:'Welche Rechtfertigungsmuster treten auf?\nWie verändern sich diese im Verlauf?\nWelche Unterschiede zeigen die beiden Figuren?',feasibility:'Eine vollständige Textausgabe ist verfügbar. Die Analyse beschränkt sich auf zwei Figuren; Kategorien werden zunächst an einer Szene getestet.',method:'Literatur- / Textanalyse',material:'Primärtext: Friedrich Dürrenmatt, Der Besuch der alten Dame. Ausgabe, Jahr und Seitenangaben nachtragen. Alle Äusserungen der zwei ausgewählten Figuren erfassen.',procedure:'Textstellen sammeln, Kontext notieren und nach moralischer, wirtschaftlicher und gemeinschaftlicher Begründung kategorisieren. Kategorien am Material überprüfen.',analysis:'Belegstellen nach Figur und Akt vergleichen; widersprüchliche Fälle diskutieren. Aussagen immer mit Akt und Seitenangabe belegen.',limits:'Die Interpretation gilt für den gewählten Text und die ausgewählten Figuren. Mehrdeutigkeit und Gegenbeispiele berücksichtigen.',keywords:'Dürrenmatt AND Besuch der alten Dame AND Moral\nGüllen Verantwortung Rechtfertigung',places:'Schulbibliothek; Bibliothekskatalog; literaturwissenschaftliche Fachdatenbanken.',literature:'Noch keine bibliografisch geprüfte Sekundärliteratur erfasst. Primärtextausgabe vollständig ergänzen.',sourcecheck:'Wissenschaftliche Kommentare nach Autorschaft, Belegen und Bezug zur Frage auswählen.',researchlog:'Nächster Schritt: Katalogsuche dokumentieren und zwei geeignete Fachbeiträge prüfen.',outline:'1. Einleitung\n2. Begriffe und Forschungsstand\n3. Methode\n4. Analyse nach Akten\n5. Vergleich und Diskussion\n6. Fazit',workflow:'Wöchentliches Arbeitsjournal; Belegliste mit Seitenangaben; Sicherung an zwei Orten.',meetings:'Konzeptfreigabe; Rückmeldung zum Kategoriensystem; Besprechung einer ersten Analyse.',risks:'Zu wenige Belege: Auswahl mit Betreuung prüfen. Zu breites Kategoriensystem: auf drei begründete Kategorien beschränken.',resources:'Textausgabe und Bibliothekszugang; schulische Zitierregeln klären.',hours:'5'};state.tasks=[];state.step=0;save();render();toast('Illustratives Beispiel geladen – Literatur noch prüfen.')};render();warnings();
